import js from "@eslint/js";
import globals from "globals";
import tseslint from "typescript-eslint";
import reactHooks from "eslint-plugin-react-hooks";
import reactRefresh from "eslint-plugin-react-refresh";
import playwright from "eslint-plugin-playwright";

export default tseslint.config(
  // Global ignores
  {
    ignores: [
      "dist/",
      "src-tauri/",
      "node_modules/",
      "scripts/",
      "ISALAB-TR-improvements/",
      "src/bindings.ts", // Auto-generated by specta
    ],
  },

  // Base rules
  js.configs.recommended,

  // TypeScript rules
  ...tseslint.configs.recommended,

  // React + Hooks rules for source files
  {
    files: ["src/**/*.{ts,tsx}"],
    plugins: {
      "react-hooks": reactHooks,
      "react-refresh": reactRefresh,
    },
    languageOptions: {
      globals: {
        ...globals.browser,
      },
      parserOptions: {
        ecmaFeatures: { jsx: true },
      },
    },
    rules: {
      // React Hooks recommended rules (but not React Compiler experimental ones)
      "react-hooks/rules-of-hooks": "error",
      "react-hooks/exhaustive-deps": "warn",

      // Allow constant exports for barrel files and shadcn/ui pattern
      "react-refresh/only-export-components": [
        "warn",
        { allowConstantExport: true },
      ],

      // Practical TypeScript rules
      "@typescript-eslint/no-unused-vars": [
        "warn",
        {
          argsIgnorePattern: "^_",
          varsIgnorePattern: "^_",
        },
      ],
      "@typescript-eslint/no-explicit-any": "warn",
      "@typescript-eslint/no-require-imports": "off",
    },
  },

  // Relax rules for UI component library (shadcn/ui pattern)
  {
    files: ["src/components/ui/**/*.tsx"],
    rules: {
      "react-refresh/only-export-components": "off",
    },
  },

  // Fechas: prohibido derivar "hoy" de toISOString().slice(0, 10).
  //
  // toISOString devuelve la fecha UTC: en Colombia (UTC-5) a partir de las
  // 19:00 apunta al día siguiente, y la cola de recepción, la agenda y el mock
  // de los E2E quedaban un día desfasados. Usa localDateISO() (src/lib/utils.ts)
  // o las helpers de fecha local del mock.
  {
    files: ["src/**/*.{ts,tsx}", "e2e/**/*.{js,ts}"],
    rules: {
      "no-restricted-syntax": [
        "error",
        {
          selector:
            "CallExpression[callee.property.name='slice'][callee.object.callee.property.name='toISOString'][arguments.0.value=0][arguments.1.value=10]",
          message:
            "No derives la fecha de toISOString().slice(0, 10): es UTC y de noche apunta al día siguiente. Usa localDateISO() (src/lib/utils.ts) o la fecha local del mock E2E.",
        },
      ],
    },
  },

  // Tests E2E: preset recomendado de Playwright. Cubre las trampas que dejan
  // la suite lenta o muda: test.only, page.waitForTimeout, expect() dentro de
  // condicionales, await olvidados en aserciones, selectores/element handles
  // obsoletos, red `networkidle`, etc. El preset se acota a e2e/ (los specs),
  // porque sus reglas no aplican al código de src/.
  {
    files: ["e2e/**/*.ts"],
    ...playwright.configs["flat/recommended"],
  },

  // Tests E2E: se lintean solo las reglas que aportan valor ahí. Los specs
  // usan patrones de Playwright (callbacks de page.on, awaits sueltos) que las
  // reglas de React/TS del proyecto marcarían sin motivo.
  {
    files: ["e2e/**/*.{js,ts}"],
    languageOptions: {
      globals: { ...globals.browser, ...globals.node },
    },
    rules: {
      "@typescript-eslint/no-unused-vars": "off",
      "@typescript-eslint/no-explicit-any": "off",
      "no-empty": "off",
      "no-unused-vars": "off",
    },
  },

  // Relax rules for test files
  {
    files: ["src/**/*.test.ts", "src/**/*.test.tsx"],
    rules: {
      "@typescript-eslint/no-explicit-any": "off",
      "no-constant-binary-expression": "off",
    },
  },
);
